"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Razmak od početka / kraja čini od prirubnice djelomičnu prirubnicu. Dodatni zatvoreni profili u skici postaju izrezi u ploči. Provrti i prozori u prirubnici: sredina duž brida (kod zakrivljenog brida duž luka), sredina od kraja savijanja, veličina – pojavljuju se i u razvijenom obliku. Ako zakrivljeni brid bez prijeloma prelazi u susjedni brid i oba imaju prirubnicu s istim kutom savijanja, prirubnice prelaze jedna u drugu bez oslobodnog izreza. „Kontura iz skice“ izrezuje zatvorene profile skice iz prirubnice: njezin X ide duž brida, njezin Y u prirubnicu, nulta točka leži na početku brida na kraju savijanja (može se pomicati).",
