"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Odaberite sve plohe koje trebaju nestati (kod džepa stijenke i dno, kod provrta stijenku, kod zaobljenja zaobljenu plohu). Susjedne plohe produljuju se preko praznine. Korak se ponovno izračunava pri promjenama tijela; pri prvom pokretanju učitava se veliko geometrijsko jezgro (nekoliko sekundi).",
