"Das Bild konnte nicht gelesen werden.":"Slika se nije mogla pročitati.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Slika leži kao predložak na ravnini. Zatim u prozoru svojstava podesite veličinu, položaj, zakret i neprozirnost (npr. širinu prema poznatoj dimenziji).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Rezultat geometrijske jezgre nije čitljiv",
"Das Ergebnis konnte nicht geschrieben werden":"Rezultat se nije mogao zapisati",
"Das Maß muss größer als 0 sein.":"Kota mora biti veća od 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Mreža ostaje trokutna mreža (nije B-Rep). Uređivanje pod MREŽA: Popravi, Smanji, Zagladi, Presjek ravninom … 3D strategije glodanja u izradi mogu je izravno obrađivati.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"Mreža ima trokuta: {0}. Svaki postaje ploha tijela – to dugo traje i usporava tijelo. Obično je bolje prije toga „Smanji“.\n\nIpak pretvoriti?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"Mreža nije zatvorena. Prvo izvedite „Popravi“ – tijelo treba zatvorenu ljusku.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"Mreža se prostire u Z od {0} do {1} mm, u X od {2} do {3} mm, u Y od {4} do {5} mm. Točke koje od pravca odstupaju manje od tolerancije otpadaju.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profil ne smije sjeći os. Otvorena linija u skici može poslužiti kao os.",
"Das Profil mit den jetzigen Werten überschreiben":"Prepisati profil trenutačnim vrijednostima",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profil se vodi duž linije/polilinije. Profil najbolje crtati okomito na početak putanje (npr. profil na XZ, putanja na XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profil se utiskuje izdignuto ili udubljeno od ravnine skice.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Pripremak je kvadar oko odabranog tijela (plus pomak).",
"Das Setup hat keine Operationen.":"Setup nema operacija.",
"Das Teil ist für die Senkung zu dünn (Senktiefe {0} mm, Dicke {1} mm).":"Dio je pretanak za upuštanje (dubina upuštanja {0} mm, debljina {1} mm).",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Alat glođe u krugovima čije se središte pomiče duž utora. Nikad nije u zahvatu cijelom širinom – to dopušta velike dubine rezanja i štedi glodalo i vreteno. Glodalo bi trebalo imati oko 60 % širine utora.",
"Das Werkzeug schneidet die Fläche nicht":"Alat ne siječe plohu",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Alat reže u smjeru odabranih ploha dok ne postigne zadane dodatke.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Alat uranja okomito poput svrdla, red po red, do modela plus dodatak. Sila rezanja djeluje duž vretena: prikladno za duge alate, duboke šupljine i manje krute strojeve. Alat mora rezati preko središta.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Alat izbjegava ove plohe uz poštivanje zadanih sigurnosnih razmaka (stezaljke, škripac).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Alat izbjegava ove plohe dok obrađuje obližnje plohe i poštuje sigurnosne razmake.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Prvi Esc prekida samo alat ili odabir – višak Esc-a ne zatvara skicu",
"Das ist eine runde Fläche – bitte eine ebene Fläche anklicken.":"Ovo je okrugla ploha – kliknite ravnu plohu.",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Ovo nije provrt (zaobljenje ili čep) – kliknite unutarnju stijenku provrta.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Ovo nije provrt (cilindrična ploha) – kliknite stijenku provrta.",
"Das ist keine WerkFab-Design-Datei.":"Ovo nije WerkFab datoteka dizajna.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Ovo nije kosi brid – kliknite oba kraja brida skošenja.",
"Datei":"Datoteka",
"Datei ist keine WerkFab-Einstellungsdatei.":"Datoteka nije datoteka postavki programa WerkFab.",
"Datei konnte nicht geöffnet werden:":"Datoteku nije moguće otvoriti:",
