"Deckkraft der Fenster":"Neprozirnost prozora",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Promjer bi postao nula ili negativan – smanjite razmak",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Glodalo za navoje radi u punom materijalu: prethodno oglodajte rukavac (2D kontura izvana oko rukavca do dubine navoja).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Tijelo nema obris na ovoj ravnini.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Tijelo se preuzima kao mreža s trokutima prikaza. Samo tijelo ostaje sačuvano; kasnije izmjene tijela ne mijenjaju mrežu.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Tijelo se skenira oko svoje okomite središnje osi i sprema kao kontura držača (odsječci) u knjižnicu alata dokumenta.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Točka oko koje se pogled okreće (kod slobodnog orbitiranja). „Ispod pokazivača miša”: mjesto na modelu na kojem počinje okretanje.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Polumjer ravnomjerno raste od početka do kraja svakog odabranog brida. Koji je kraj početak određuje brid – po potrebi zamijenite.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Rub plohe je zatvoreni lanac: s opcijom „neprekinuto” polumjer teče jednom uokolo, a bez nje na svakom bridu zasebno od početnog do završnog polumjera.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Rez ne pogađa nijedno tijelo – ne uklanja se materijal.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Tekst stoji kao komentar na ovom mjestu u programu.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Prvi razmak mjeri se na plohi koja je više okrenuta prema gore (Z); drugi razmak odnosno kut odnosi se na drugu plohu. „Zamijeni strane” to obrće. Tangencijalno povezani bridovi uključuju se automatski.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Odabrano tijelo je pripremak (npr. lijevani ili kovani odljevak). Samo se ne obrađuje.",
"Der große Geometriekern ist noch nicht geladen":"Veliko geometrijsko jezgro još nije učitano",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Učitava se velika geometrijska jezgra – ovaj će se korak uskoro sam preračunati",
