"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Vlastite kote i napomene mogu se mišem povlačiti po listu (razmak kotne linije, kut pokazne linije, radijus kutnog luka). Klik na dva kuta = linearna kota. Klik na rub kružnice u tlocrtu = promjer (odnosno radijus). Kut: prvo vrh, zatim po jedna točka na oba kraka. Skošenje: oba kraja kosog brida – daje npr. 2×45°. U tekstualnom polju iza svake kote nalazi se dodatak poput ±0,1, H7 ili 4×.",
