"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Najprije kliknite plohu na tijelu koje se pomiče, zatim ciljnu plohu na drugom tijelu. Tijelo se zakreće i pomiče dok prva točka klika ne leži na drugoj i dok plohe ne prilježu jedna uz drugu.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Najprije kliknite brid na tijelu koje se pomiče, zatim ciljni brid na drugom tijelu. Ravni bridovi poklapaju se (sredina na sredinu); kod kružnih bridova – provrt i čep – osi se usmjeravaju jednako, a središta se spajaju.",
