"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Prvo odaberite skicu ili konstrukcijsku ravninu – tada Ctrl+8 gleda okomito na nju.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Prvo izradite tijelo u KONSTRUKCIJA ili umetnite mrežu (STL).",
