"Fläche anklicken – die Bohrung entsteht mit":"Kliknite plohu – provrt nastaje istodobno",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Kliknite plohu: u svakoj točki klika nastaje prolazni provrt za vijak (ISO 273, srednji niz) kroz sve dijelove koji tamo leže jedan na drugom – za vijke s upuštenom glavom s 90° stožastim upuštanjem, za vijke s cilindričnom glavom po želji s cilindričnim upuštanjem (DIN 974-1, niz 1) dubokim koliko i glava. Vijak odmah sjedi u provrtu. Provrt i vijak mogu se poslije mijenjati na vremenskoj crti.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Kliknite plohu tijela: njezin rub dolazi u skicu kao kontura. Klik na brid projicira samo taj brid (kružnice ostaju kružnice). Projicirana geometrija je ljubičasta.",
"Fläche ersetzen":"Zamijeni plohu",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Zamijeni plohu: premjesti ravnu plohu na drugu ravninu – tijelo raste ili se skraćuje",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Površina iza prozora – vrijedi kad je gore odabran dizajn „Vlastiti“",
"Fläche löschen":"Izbriši plohu",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Izbriši plohu: ukloni provrte, džepove, zaobljenja ili skošenja – susjedne plohe zatvaraju prazninu",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"Prikaži plohu ili brid ispod pokazivača miša u boji",
"Fläche versetzen":"Pomakni plohu",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Pomakni plohu: pomicanje ravnih ploha, promjena promjera provrta i osovinskih čepova",
