"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Datoteke Fusion 360 (.f3d) zatvoreni su Autodeskov format i ne mogu se čitati.\n\nU Fusion 360 odaberite Datoteka → Izvoz → STEP (.stp) i uvezite tu datoteku ovdje.",
"Fusion-360-Postprozessor „{0}“ übernommen:\n\n• {1}":"Fusion 360 postprocesor „{0}“ preuzet:\n\n• {1}",
"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Prolazi sve oštre vanjske bridove dostupne odozgo i lomi ih za dubinu skidanja srha – glodalom za skošenje kao skošenje (os alata okomita, vrh izvan brida), kuglastim/lollipop glodalom zaobljeno.",
