"Für eine Bohrung Ø {0} mm gibt es in dieser Reihe keine passende Schraube.":"Za provrt Ø {0} mm u ovoj seriji nema odgovarajućeg vijka.",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Za kose smjerove izradite konstrukcijsku os (kroz dvije točke, valjak ili dvije ravnine) – ona će se tada ovdje pojaviti kao smjer.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"Za trohoidno glodanje duž linije navedite širinu utora",
