"Gefräst wird von unten nach oben im Gleichlauf. M6 = Nenn-Ø 6, Steigung 1; M8 = 8 / 1,25; M10 = 10 / 1,5.":"Glođe se odozdo prema gore istosmjerno. M6 = nazivni Ø 6, uspon 1; M8 = 8 / 1,25; M10 = 10 / 1,5.",
