"Gemeinsame Schnittkanten nur einmal schneiden":"Zajedničke rubove reza rezati samo jednom",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Zajednički rubovi reza: ako su dva zasjeka udaljena točno za jednu širinu reza (pri slaganju upišite širinu reza kao razmak), njihova se putanja na zajedničkom rubu poklapa i reže se samo jednom. Ulaz u rez nikad ne leži u susjednom dijelu: ako pored konture nema slobodnog otpada, probija se na konturi. Nakon „Pregleda“ slika za svaku ploču prikazuje putanju prije spremanja datoteka.",
"Genauigkeit":"Točnost",
