"Geometriekern konnte nicht geladen werden ({0}) – OpenCascade bleibt aktiv.":"Geometrijsku jezgru nije moguće učitati ({0}) – OpenCascade ostaje aktivan.",
"Geometriekern: OpenCascade (über replicad) · Darstellung: three.js · Einstellungen werden auf diesem Rechner gespeichert.":"Geometrijska jezgra: OpenCascade (putem replicada) · Prikaz: three.js · Postavke se spremaju na ovom računalu.",
