"Gerade (radial)":"Ravno (radijalno)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Ravne linije skice koje ne pripadaju nijednom profilu (i pomoćne linije). Savijanje: linija je sredina zone savijanja, a skica je ondje kroj – najveći komad ploče ostaje na mjestu, sve s druge strane linije zakreće se sa svojim prirubnicama. Linija vrijedi preko cijele ploče. Ukrutno rebro: rebro uz liniju, okruglo u presjeku i na krajevima; lim zadržava svoju debljinu.",
"Geraden, Bögen und Kreise":"Pravci, lukovi i kružnice",
"Gerader Teil (nach der Biegung)":"Ravni dio (nakon savijanja)",
