"Geschlossen":"Zatvoreno",
"Geschlossen (Gehrung)":"Zatvoreno (kosi spoj)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Zatvoreno: jezičci na dva susjedna brida idu do simetrale kuta i tamo ostavljaju zazor. Rasterećenje kuta nalazi se gdje se sijeku zone savijanja – na razvijenom obliku i na savijenom dijelu. I jezičac na zakrivljenom bridu u pravom se kutu reže na geringu (tamo bez rasterećenja kuta).",
"Geschlossene Kette {0}":"Zatvoreni lanac {0}",
"Geschlossene Profile begrenzen den Bereich.":"Zatvoreni profili ograničavaju područje.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Ispuni zatvorene profile aktivne skice bojom",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Zatvoreni profili postaju ravne plohe – npr. poklopac i dno, kako bi se plohe zatim zašile u tijelo.",
