"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Uvezena tijela nemaju povijest konstruiranja, ali se mogu dalje obrađivati (zaobljenje, skošenje, izrezivanje …) i koristiti za CAM. Opcijom „Y os prema gore” modeli iz programa s osi Y prema gore ispravno se postavljaju.",
