"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Prva krivulja svake skice – otvorena ili zatvorena. Krivulje se povezuju ljuskom (ploha bez debljine).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Jedna datoteka po ploči. Putanja ide u otpadu uz konturu, na pola širine reza (kod glodanja pola glodala); izrezi dolaze prije konture svog dijela, a svaka kontura počinje ulazom u rez iz otpada. Žaluzine se režu po svojoj liniji. Pridržni mostići: toliko mjesta po konturi ostaje neprerezano (laser, plazma, vodeni mlaz: mlaz se ondje isključuje; glodanje: glodalo se podiže na pola debljine lima); konture kraće od 40 mm nemaju ih. „Upravljanje“ određuje čime se mlaz uključuje i isključuje; vrijeme probijanja u programu stoji kao G4, osim ako upravljanje samo probija. Nulta točka je donji lijevi kut ploče, kod glodanja je Z0 gornja strana lima. Program provjerite na stroju ili u NC simulatoru prije uporabe.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Svaka os zasebno: kliknite brid, vrh, plohu ili provrt. Osi koje nisu postavljene preuzimaju se iz točke pripremka.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Svaka operacija kao potprogram (LBL) na kraju programa, poziv s CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Svaka kružnica skice je središte provrta. Buši se suprotno od normale skice (u materijal).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Svaka kružnica skice ponavlja se zakrenuta oko središta (u koordinatama skice) – kružnica na udaljenosti polumjera diobene kružnice daje kružni raspored provrta.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Svaka kružnica skice postaje mreža: razmaci u X i Y skice (i negativni).",
