"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Konture prate rub tamnih površina. Središnja linija prolazi sredinom poteza – prikladno za gravure i linijske crteže. „Pravci, lukovi i kružnice” prepoznaje ravne bridove, oštre kutove, zaobljenja i kružnice; „Polilinije” prate sliku točku po točku. Mjerilo zatim po potrebi prilagodite pomoću „Kalibriraj predložak” ili „Skaliraj”.",
