"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Krivulje skice na čeonoj plohi (poprečno na os vrtnje) pogonjenim glodalom duž Z (X i C voze zajedno; Fanuc: polarna interpolacija G12.1). Otvorene krivulje glođu se naprijed-natrag. Dubina od čeone plohe.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Krivulje skice koja leži uzduž osi vrtnje namataju se na opseg i glođu pogonjenim glodalom koje pokazuje prema osi (Z i C voze zajedno; Fanuc: cilindrična interpolacija G7.1). Ravnina skice određuje kut na kojem kontura leži; vodoravne dužine u skici postaju lukovi oko dijela. Dubina od vanjskog promjera.",
"Kurzbefehl":"Prečac",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Kratke putove (do razmaka držanja) alat vozi dolje prijelaznim posmakom umjesto preko visine povlačenja – bez provjere sudara, stoga neka bude malo.",
