"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"S potpornim točkama polumjer prolazi kroz zadane vrijednosti (položaj u % duljine brida). To izračunava veliko geometrijsko jezgro; pri prvom pokretanju učitavanje traje nekoliko sekundi.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D sondom se ne može rezati",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Usporedba s gotovim dijelom: zeleno = na mjeru, plavo = zaostali materijal, crveno = preduboko",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Pomaknite miš pokraj konture (strana određuje smjer) · Esc završava",
"Mit diesem Werkzeug kann nicht gefräst werden":"Ovim se alatom ne može glodati",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"S ureznikom samo ciklus „Urezivanje navoja“ – ciklus bušenja bi ga slomio",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"S više pomaka dubina navoja glođe se u koracima koji svaki skidaju otprilike jednako – štedi male glodala za navoje i tvrde materijale. Prazan prolaz vozi posljednju putanju još jednom bez pomaka.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"S „Ciklusima bušenja“ u NC programu izlaze ciklusi upravljanja (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), inače raspisana gibanja.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Uz „Zadrži original“ original i zrcalna slika postaju jedna mreža; točke na ravnini zrcaljenja se spajaju – iz otvorene polovice tako nastaje zatvoren dio.",
