"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Samo pravokutni i kružni džepovi mogu se izvesti kao ciklus upravljanja",
"Nur Skizze":"Samo skica",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Obrađivati samo ono što je veće glodalo ostavilo u kutovima.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Slijediti samo ona mjesta konture koja veće glodalo nije doseglo (unutarnji kutovi, uska mjesta). Bez lukova ulaska/izlaska, mostića i završnih prolaza; korekcija u računalu.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Samo tamo gdje referentni alat nije dosegnuo: plošna područja paralelno, strma područja kao vodena linija. S alatom s popisa uračunava se i njegov oblik – na primjer što torusno glodalo ostavlja u ukrućenjima.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Samo ravne plohe mogu poslužiti kao ravnina skice.",
"Nur ebene Flächen können extrudiert werden":"Ekstrudirati se mogu samo ravne plohe",
"Nur ebene Flächen lassen sich ersetzen":"Zamijeniti se mogu samo ravne plohe",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Pomaknuti (offset) se mogu samo ravne i cilindrične plohe (provrti, čepovi)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Samo ravne plohe okrenute prema gore, prema alatu (vodoravne u ovom setupu).",
"Nur für Außen-Drehmeißel":"Samo za vanjske tokarske noževe",
"Nur in Operationen verwendete":"Samo korišteni u operacijama",
"Nur in diesem Projekt":"Samo u ovom projektu",
