"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Utor uzduž osi vrtnje (npr. utor za pero) pogonjenim glodalom koje pokazuje prema osi; glavno vreteno drži dio kao C os. Širina utora = Ø glodala. Početak/kraj Z u Z modela; ako utor seže do čeone plohe, glodalo ulazi sprijeda, inače uranja na početku. Dubina od vanjskog promjera.",
