"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Otvorene ili zatvorene krivulje izvlače se okomito na skicu – nastaje ploha (stijenka bez debljine). Pomoću „Zadebljaj” ili „Zašij” iz nje nastaje volumen.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Otvorene ili zatvorene krivulje rotiraju se oko osi – nastaje ploha, a ne volumen.",
"Ohne Mutter":"Bez matice",
"Ohne eigene Taste gilt der Standard „{0}“.":"Bez vlastite tipke vrijedi zadano „{0}“.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Bez opcije „Modelirano” navoj se samo prikazuje (brzo). Kod modeliranog navoja oblik navoja se doista izrezuje, npr. za 3D ispis. Provrt za M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP tokarenje",
"Okuma OSP-M Fräsen":"Okuma OSP-M glodanje",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 tamo ne idu na strojne koordinate (G53 poništava korekciju duljine alata) – povlačenje na sigurnosnu visinu, XY referentni hod nije ispisan",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: funkcija zaglađivanja nije ispisana (G5.1 je Fanuc) – Hi-Cut/Super-NURBS podesite na stroju",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: korekcija+alat+oštrica (npr. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (sve funkcije)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: sve funkcije. Rust jezgra (truck, eksperimentalno): osnovna tijela, ekstruzija, rotacija, provrt, niz, zrcaljenje, pomicanje, skaliranje, kombiniranje i STEP izvoz – ostale značajke označene su kao „još nije podržano“.",
