"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"Projiciraj (J): kliknite plohu ili brid tijela – njihova projekcija dolazi u skicu",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"Projiciranje bridova i ploha treba puno tijelo standardne jezgre – obris tijela i krivulje presjeka rade i s mrežama.",
