"Prägung":"Utisak",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Utisak {0}: kontura je uža od 2 × debljina lima – ne ostaje šupljina.",
"Prägung {0}: lässt sich so nicht formen":"Utisak {0}: ovako se ne može oblikovati",
"Prägung {0}: mit dieser Wandschräge lässt sie sich nicht formen":"Utisak {0}: s ovim se kutom stijenke ne može oblikovati",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Utisak {0}: {1} mm veće je od 3 × debljina lima – s okomitom stijenkom lim puca.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Utisak: kontura se ne izrezuje, nego se za zadanu visinu utiskuje iz ploče; drugo polje je kut stijenke (0° = okomito). Upušteni utisak: rub okruglog provrta utiskuje se u stožac od 90° – za upuštene vijke u tankom limu (− prema dolje: vijak odozgo).",
