"Rechteck-/Kreistasche erkannt ({0}) – Heidenhain: CYCL DEF 251/252 an der Taschenmitte. Die Steuerung fräst mit ihrer eigenen Strategie; Simulation und Bahn hier sind die WerkFab-Bahn.":"Prepoznat pravokutni/kružni džep ({0}) – Heidenhain: CYCL DEF 251/252 u sredini džepa. Upravljanje glođe vlastitom strategijom; simulacija i putanja ovdje su WerkFab putanja.",
