"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Stvarno međusobno izračunava dvije zatvorene mreže: unutarnje plohe nestaju, rubovi presjeka ponovno se umrežuju. Računa se samo ondje gdje se dvije mreže mogu susresti – velika mreža s malim zahvatom stoga je brza. Ako se dvije velike mreže potpuno preklapaju, prije toga „Smanji“.",
