"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Vijčani spoj: podloške i matica postavljaju se zajedno s vijkom u jednom koraku na svaki odabrani provrt. Debljina stezanja je duljina provrta – kroz više dijelova ako su im provrti u osi i naliježu jedan na drugi. S maticom se predlaže najkraća prednosna duljina kod koje vijak viri iz matice za dva navoja.",
