"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: Postprocesor bez ciklusa tokarenja – ispisano kao putanja",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: postprocesor bez polarne interpolacije – plohe se ispisuju kao kratki koraci X/C (C u stupnjevima); posmak tada ovisno o upravljanju ne vrijedi uzduž putanje. Bolje je ispuniti predložak „Polarna interpolacija uklj./isklj.“",
