"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"„+“ = alat će se novo izraditi. Podaci rezanja su orijentacijske vrijednosti za tvrdi metal ({0}){1}; hlađenje: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Uklopiti jedno u drugo“ slaže krojeve u praznine i uvale susjednih dijelova te u njihove izreze (bez okretanja za 90° samo okrenuto za 180°); razmak se nikada ne smanjuje. Bez kvačice leže u redovima prema svom opisanom pravokutniku. Uz „Skica + tijela“ nastaju ravna tijela debljine lima koja se u izradi mogu izrezati 2D konturom.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"„Unutra/Izvana“ zahtijeva zatvorene konture – otvorene krivulje glodajte s „Na krivulji“",
